(async () => {
 for (const root of process.argv.slice(2)) {
  const source = fs.readFileSync(path.join(root,'package/dist/transport/repl-bridge.js'),'utf8');
  for (const platform of ['win32','linux']) {
   const paths = platform === 'win32' ? path.win32 : path.posix;
   for (const c of [
    {name:'new-only', files:['qbrain-ai-repl'], want:'qbrain-ai-repl'},
    {name:'legacy-only', files:['mcpserver-repl'], want:'mcpserver-repl'},
