    {name:'command-override',files:['qbrain-ai-repl'],env:{MCPSERVER_REPL_COMMAND:'custom-repl'},want:'custom-repl'},
    {name:'bin-override',files:['qbrain-ai-repl'],env:{MCPSERVER_REPL_BIN:'custom-bin',MCPSERVER_REPL_COMMAND:'custom-repl'},want:'custom-bin'}
   ]) {
    const ext=platform === 'win32'?'.exe':'';
    const env={PATH:platform==='win32'?'C:\\tools':'/tools',PLUGIN_AGENT_NAME:'Codex',...c.env};
    const commands=[];
    const mod={exports:{}};
    const mocks={
     child_process:{spawn:(cmd,args,opts)=>{commands.push({cmd,args,opts});const p=new EventEmitter();p.stderr=new EventEmitter();p.stdout=new EventEmitter();p.exitCode=null;p.killed=false;return p;}},
     fs:{existsSync:p=>c.files.some(f=>p===paths.join(env.PATH,f+ext)),statSync:()=>({isDirectory:()=>false})},
     path:paths,readline:{createInterface:()=>new EventEmitter()},'js-yaml':{}
    };
    vm.runInNewContext(source,{exports:mod.exports,module:mod,require:n=>{if(!(n in mocks))throw Error(n);return mocks[n];},process:{env,platform,cwd:()=>root,stderr:{write:()=>{}}},setTimeout,clearTimeout,console},{filename:root+'/repl-bridge.js'});
    assert.equal(mod.exports.resolveReplCommand(),c.want);
