    assert.deepEqual(Array.from(commands[0].args),['--agent-stdio','--agent','Codex']);
    console.log(JSON.stringify({bundle:path.basename(root),platform,case:c.name,selected:commands[0].cmd,pass:true}));
   }
  }
 }
})().catch(e=>{console.error(e);process.exitCode=1;});
